Based on a patch originally written by Benjamin Tissoires.

Signed-off-by: Nestor Lopez Casado <nlopezcasad@logitech.com>
Signed-off-by: Jiri Kosina <jkosina@suse.cz>
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>

Here is the root cause:
The bug was caused by a race condition introduced after a previous commit, which led to the `hid-core` discarding incoming packets while the HID driver's probe function was executing. This resulted in the loss of control packets necessary for the enumeration process of the `hid-logitech-dj`, as these packets must be received in conjunction with mouse and keyboard packets. Consequently, the driver was unable to recognize paired devices, leading to issues in device communication.

Here is the patch:
 					size_t count,
 					unsigned char report_type);
+static int logi_dj_recv_query_paired_devices(struct dj_receiver_dev *djrcv_dev);

 static void logi_dj_recv_destroy_djhid_device(struct dj_receiver_dev *djrcv_dev,

 static void logi_dj_recv_add_djhid_device(struct dj_receiver_dev *djrcv_dev,
 					  struct dj_report *dj_report)
 {
 	/* Called in delayed work context */
 	struct hid_device *djrcv_hdev = djrcv_dev->hdev;
 	struct usb_interface *intf = to_usb_interface(djrcv_hdev->dev.parent);
 	struct usb_device *usbdev = interface_to_usbdev(intf);
 	struct hid_device *dj_hiddev;
 	struct dj_device *dj_dev;

 	/* Device index goes from 1 to 6, we need 3 bytes to store the
 	 * semicolon, the index, and a null terminator
 	 */
 	unsigned char tmpstr[3];

 	if (dj_report->report_params[DEVICE_PAIRED_PARAM_SPFUNCTION] &
 	    SPFUNCTION_DEVICE_LIST_EMPTY) {
 		dbg_hid("%s: device list is empty\n", __func__);
+		djrcv_dev->querying_devices = false;
 		return;
 	}

 	if ((dj_report->device_index < DJ_DEVICE_INDEX_MIN) ||
 	    (dj_report->device_index > DJ_DEVICE_INDEX_MAX)) {
 		dev_err(&djrcv_hdev->dev, "%s: invalid device index:%d\n",
 			__func__, dj_report->device_index);
 		return;
 	}

+	if (djrcv_dev->paired_dj_devices[dj_report->device_index]) {
+		/* The device is already known. No need to reallocate it. */
+		dbg_hid("%s: device is already known\n", __func__);
+		return;
+	}
+
 	dj_hiddev = hid_allocate_device();
 	if (IS_ERR(dj_hiddev)) {
 		dev_err(&djrcv_hdev->dev, "%s: hid_allocate_device failed\n",
 			__func__);
 		return;
 	}

 	dj_hiddev->ll_driver = &logi_dj_ll_driver;
 	dj_hiddev->hid_output_raw_report = logi_dj_output_hidraw_report;

 	dj_hiddev->dev.parent = &djrcv_hdev->dev;
 	dj_hiddev->bus = BUS_USB;
 	dj_hiddev->vendor = le16_to_cpu(usbdev->descriptor.idVendor);
 	dj_hiddev->product = le16_to_cpu(usbdev->descriptor.idProduct);
 	snprintf(dj_hiddev->name, sizeof(dj_hiddev->name),
 		"Logitech Unifying Device. Wireless PID:%02x%02x",
 		dj_report->report_params[DEVICE_PAIRED_PARAM_EQUAD_ID_MSB],
 		dj_report->report_params[DEVICE_PAIRED_PARAM_EQUAD_ID_LSB]);

 	usb_make_path(usbdev, dj_hiddev->phys, sizeof(dj_hiddev->phys));
